package com.hospital.smartqueue.department.application;
import com.hospital.smartqueue.common.domain.*; import com.hospital.smartqueue.common.infrastructure.AuditService; import com.hospital.smartqueue.department.domain.Department; import com.hospital.smartqueue.department.infrastructure.DepartmentRepository; import com.hospital.smartqueue.hospital.infrastructure.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class DepartmentService { private final DepartmentRepository departments; private final HospitalRepository hospitals; private final BranchRepository branches; private final AuditService audit; public DepartmentService(DepartmentRepository d,HospitalRepository h,BranchRepository b,AuditService a){departments=d;hospitals=h;branches=b;audit=a;} private void valid(UUID h,UUID b){if(!hospitals.existsById(h)||branches.findById(b).filter(x->x.getHospitalId().equals(h)).isEmpty())throw new NotFoundException("Branch not found in hospital context");} private String n(String s){if(s==null||s.trim().isEmpty())throw new DomainException("Name is required");return s.trim();} @Transactional public Department create(UUID h,UUID b,String n){valid(h,b); Department d=departments.save(new Department(UUID.randomUUID(),b,n(n)));audit.record("DEPARTMENT_CREATED","DEPARTMENT",d.getId(),h,null);return d;} public List<Department> list(UUID h,UUID b){valid(h,b);return departments.findByBranchId(b);} }
